"use client";

import { useMemo, useSyncExternalStore } from "react";
import { cn } from "@/lib/utils";
import { resolveLocale, toDate } from "../../comment-thread/lib/format-time";

export interface EditedSuffixProps {
  /** Visible label text (e.g. "(edited)"). */
  label: string;
  /** Exact edit timestamp — rendered as the `title` attribute for a hover tooltip. */
  editedAt: Date | string | number;
  /** BCP 47 locale of the tooltip. Default "en". */
  locale?: string;
  /** IANA time zone of the tooltip. Default: the runtime's (read after mount, so the server and the first client render agree). */
  timeZone?: string;
  className?: string;
}

const noopSubscribe = () => () => {};

function formatExact(
  input: Date | string | number,
  locale: string | undefined,
  timeZone: string | undefined,
): string | undefined {
  const date = toDate(input);
  if (Number.isNaN(date.getTime())) return undefined;
  try {
    return new Intl.DateTimeFormat(resolveLocale(locale), {
      dateStyle: "medium",
      timeStyle: "short",
      timeZone,
    }).format(date);
  } catch {
    // An invalid `timeZone` falls back to the runtime's.
    return new Intl.DateTimeFormat(resolveLocale(locale), {
      dateStyle: "medium",
      timeStyle: "short",
    }).format(date);
  }
}

/**
 * Sealed "(edited)" suffix rendered inline with the post timestamp when `post.editedAt` is set.
 * The `title` attribute exposes the exact edit timestamp on hover (browser-native tooltip).
 */
export function EditedSuffix({ label, editedAt, locale, timeZone, className }: EditedSuffixProps) {
  // Without an explicit time zone the text depends on where the code runs, so it is left out of
  // the server render and the first client render.
  const mounted = useSyncExternalStore(
    noopSubscribe,
    () => true,
    () => false,
  );
  const title = useMemo(
    () => (timeZone || mounted ? formatExact(editedAt, locale, timeZone) : undefined),
    [editedAt, locale, timeZone, mounted],
  );
  return (
    <span className={cn("shrink-0 text-muted-foreground", className)} title={title}>
      {label}
    </span>
  );
}

EditedSuffix.displayName = "EditedSuffix";

"use client";

import { Fragment, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import type { PostMention } from "../types";

export interface MentionTextProps {
  /** Plain text body (typically `post.content`). */
  content: string;
  /** Mention ranges in UTF-16 code units (end-exclusive). */
  mentions?: PostMention[];
  /** Click handler for highlighted mention spans. When omitted, mentions render as disabled buttons. */
  onMentionClick?: (mentionId: string) => void;
  /** Class for the outer wrapping `<span>`. */
  className?: string;
  /** Class applied to each highlighted mention span. Defaults paired with text-primary + hover underline. */
  mentionClassName?: string;
}

/**
 * Sealed RSC-compatible content renderer that highlights `@mention` spans
 * inside a plain text body. Sub-exported from `post-card/index.ts` per
 * Q-EB pattern for host-side opt-in via the `renderContent` slot:
 *
 * ```tsx
 * <PostCard
 *   post={post}
 *   renderContent={(p) => (
 *     <MentionText
 *       content={p.content}
 *       mentions={p.mentions}
 *       onMentionClick={(id) => router.push(`/users/${id}`)}
 *     />
 *   )}
 * />
 * ```
 *
 * Why opt-in (per F-Plan-7 closure): the default `renderContent` is
 * `<ExpandableText content={post.content}>`, which takes `content: string`
 * and can't accept the JSX-span tree this component emits. Hosts wanting
 * inline highlighting trade away the "read more" clamping; this is a
 * deliberate v0.2.0 design choice. v0.3+ may bridge by extending
 * ExpandableText to accept ReactNode children.
 *
 * Invalid ranges (negative start, end beyond content length, start ≥ end)
 * are filtered out silently — the corresponding text renders as plain.
 */
export function MentionText({
  content,
  mentions,
  onMentionClick,
  className,
  mentionClassName,
}: MentionTextProps) {
  if (!mentions || mentions.length === 0) {
    return <span className={className}>{content}</span>;
  }
  const sorted = mentions
    .filter(
      (m) =>
        m.range[0] >= 0 &&
        m.range[1] <= content.length &&
        m.range[0] < m.range[1],
    )
    .slice()
    .sort((a, b) => a.range[0] - b.range[0]);

  if (sorted.length === 0) {
    return <span className={className}>{content}</span>;
  }

  const parts: ReactNode[] = [];
  let pos = 0;
  for (let i = 0; i < sorted.length; i++) {
    const mention = sorted[i];
    const [start, end] = mention.range;
    if (start < pos) {
      // Overlapping ranges — skip the overlapping mention to avoid garbled output.
      continue;
    }
    if (start > pos) {
      parts.push(
        <Fragment key={`text-${i}`}>{content.slice(pos, start)}</Fragment>,
      );
    }
    parts.push(
      <button
        key={`mention-${mention.id}-${i}`}
        type="button"
        onClick={
          onMentionClick ? () => onMentionClick(mention.id) : undefined
        }
        disabled={!onMentionClick}
        className={cn(
          "font-medium text-primary",
          onMentionClick &&
            "hover:underline focus:underline focus:outline-none",
          !onMentionClick && "cursor-default",
          mentionClassName,
        )}
      >
        {content.slice(start, end)}
      </button>,
    );
    pos = end;
  }
  if (pos < content.length) {
    parts.push(<Fragment key="text-tail">{content.slice(pos)}</Fragment>);
  }
  return <span className={className}>{parts}</span>;
}

MentionText.displayName = "MentionText";

