import { ExternalLink } from "lucide-react";
import { cn } from "@/lib/utils";
import type { LinkPreview } from "../types";

export interface LinkPreviewCardProps {
  preview: LinkPreview;
  /**
   * Click handler — overrides the default `<a href={url} target="_blank">`
   * navigation. When provided, the card renders as a `<button>` and fires
   * the callback with the URL; when omitted, the card renders as a plain
   * anchor and opens in a new tab.
   */
  onClick?: (url: string) => void;
  className?: string;
}

/** Safe hostname extraction — falls back to the raw URL string if parsing throws. */
function getHostname(url: string): string {
  try {
    return new URL(url).hostname;
  } catch {
    return url;
  }
}

/**
 * Sealed client component rendering an OG-style link preview card below the
 * post content body and above the media block.
 *
 * Per Q-D4 lock: host pre-fetches `post.linkPreview` data; library is fully
 * fetch-free. v0.3+ may add an optional `linkPreviewFetcher` prop for
 * library-side resolution.
 *
 * Renders nothing if `preview.url` is the only populated field — bare URL
 * with no title / description / image / siteName looks empty; consumers
 * supplying just a URL should suppress via `disableLinkPreviewRender`.
 */
export function LinkPreviewCard({
  preview,
  onClick,
  className,
}: LinkPreviewCardProps) {
  const interactive = !!onClick;

  // Render-skip guard: bare URL without metadata produces an empty card.
  // The library defaults to skipping it; consumers wanting a bare URL chip
  // can render their own via the renderLinkPreview slot.
  if (
    !preview.title &&
    !preview.description &&
    !preview.image &&
    !preview.siteName
  ) {
    return null;
  }

  const body = (
    <>
      {preview.image ? (
        <div className="relative aspect-video w-full overflow-hidden bg-muted">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={preview.image}
            alt=""
            className="h-full w-full object-cover"
            loading="lazy"
          />
        </div>
      ) : null}
      <div className="flex flex-col gap-1 p-3">
        {preview.siteName ? (
          <div className="text-[10px] font-medium uppercase tracking-wide text-muted-foreground">
            {preview.siteName}
          </div>
        ) : null}
        {preview.title ? (
          <div className="line-clamp-2 text-sm font-semibold text-foreground">
            {preview.title}
          </div>
        ) : null}
        {preview.description ? (
          <div className="line-clamp-2 text-xs text-muted-foreground">
            {preview.description}
          </div>
        ) : null}
        <div className="flex items-center gap-1 text-[10px] text-muted-foreground">
          <ExternalLink className="h-3 w-3 shrink-0" aria-hidden="true" />
          <span className="truncate">{getHostname(preview.url)}</span>
        </div>
      </div>
    </>
  );

  const baseClasses = cn(
    "block overflow-hidden rounded-lg border border-border bg-card transition-colors",
    interactive
      ? "w-full text-start hover:bg-muted/50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
      : "hover:bg-muted/30",
    className,
  );

  if (interactive) {
    return (
      <button
        type="button"
        onClick={() => onClick(preview.url)}
        className={baseClasses}
      >
        {body}
      </button>
    );
  }

  return (
    <a
      href={preview.url}
      target="_blank"
      rel="noopener noreferrer"
      className={baseClasses}
    >
      {body}
    </a>
  );
}

LinkPreviewCard.displayName = "LinkPreviewCard";

"use client";

import { useMemo, type ElementType } from "react";
import { cn } from "@/lib/utils";
import { PostCard } from "../post-card";
import { defaultPostCardLabels, type Post, type PostCardProps } from "../types";

/** Makes the nested card controlled, so it follows its `post` prop instead of keeping the first one. */
const FOLLOW_PROP = () => {};

export interface RepostOfCardProps {
  /** The original post being reposted (`statefulPost.repostOf`). */
  originalPost: Post;
  /**
   * Click handler — overrides default `getHref`-based navigation. When
   * provided, the foreground click target renders as a `<button>` and fires
   * with the original post. When omitted and `getHref` is set, renders as
   * an `<a>`. When neither is set, the card is non-interactive.
   */
  onClick?: (originalPost: Post) => void;
  /** Used to derive the default href when `onClick` is omitted. */
  getHref?: PostCardProps["getHref"];
  /** Polymorphic root for the anchor case. Default `"a"`. */
  linkComponent?: PostCardProps["linkComponent"];
  /** Forwarded to the nested compact `<PostCard>` for header label strings. */
  labels?: PostCardProps["labels"];
  /** Forwarded to the nested card: locale, time zone and "now" (see `PostCardProps`). */
  locale?: PostCardProps["locale"];
  timeZone?: PostCardProps["timeZone"];
  now?: PostCardProps["now"];
  formatRelativeTime?: PostCardProps["formatRelativeTime"];
  formatCount?: PostCardProps["formatCount"];
  className?: string;
}

/**
 * Sealed client component rendering a nested counts-only mini-card for a
 * reposted post. Nests `<PostCard variant="compact" engagementMode="navigate"
 * viewerMode="viewer" engagementActions={() => []}>` per plan Q-P30 — the
 * empty-array slot suppresses the engagement bar entirely (engagement-bar
 * short-circuits when actions.length === 0), leaving only the compact header
 * and content body. Result: counts-only meta row inside the nested compact card.
 *
 * Recursion-strip: `originalPost.repostOf` is forced to `undefined` before being
 * passed down, so a repost-of-a-repost renders only one level deep.
 *
 * Polymorphic root + interaction model:
 *   - `onClick` provided → foreground `<button>` captures click + keyboard.
 *   - `getHref` provided → foreground `<LinkComponent href>` captures click +
 *     middle-click + right-click-open-in-new-tab semantics.
 *   - Neither → non-interactive.
 * The nested mini-card is wrapped in `pointer-events-none` so any descendant
 * interactivity (kebab if labels populated, mention/tag chips, etc.) cannot
 * conflict with the outer click target. The foreground click target sits at
 * `z-10` above the nested card.
 */
export function RepostOfCard({
  originalPost,
  onClick,
  getHref,
  linkComponent,
  labels,
  locale,
  timeZone,
  now,
  formatRelativeTime,
  formatCount,
  className,
}: RepostOfCardProps) {
  // Recursion-strip: prevent infinite nesting of repost mini-cards.
  const strippedOriginal = useMemo<Post>(
    () => ({ ...originalPost, repostOf: undefined }),
    [originalPost],
  );

  const overlayClasses =
    "absolute inset-0 z-10 cursor-pointer rounded-lg transition-colors hover:bg-foreground/[0.03] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring";

  const ariaLabel = (labels?.openRepost ?? defaultPostCardLabels.openRepost)(
    originalPost.author.name,
  );

  return (
    <div
      className={cn(
        "relative overflow-hidden rounded-lg border border-border bg-muted/30",
        className,
      )}
    >
      <div className="pointer-events-none">
        <PostCard
          variant="compact"
          engagementMode="navigate"
          viewerMode="viewer"
          engagementActions={() => []}
          post={strippedOriginal}
          onPostChange={FOLLOW_PROP}
          labels={labels}
          locale={locale}
          timeZone={timeZone}
          now={now}
          formatRelativeTime={formatRelativeTime}
          formatCount={formatCount}
        />
      </div>
      {onClick ? (
        <button
          type="button"
          onClick={() => onClick(originalPost)}
          className={overlayClasses}
          aria-label={ariaLabel}
        />
      ) : getHref ? (
        (() => {
          const LinkComponent: ElementType = linkComponent ?? "a";
          return (
            <LinkComponent
              href={getHref(originalPost)}
              className={overlayClasses}
              aria-label={ariaLabel}
            />
          );
        })()
      ) : null}
    </div>
  );
}

RepostOfCard.displayName = "RepostOfCard";

"use client";

import { useEffect, useMemo, useRef } from "react";
import { cn } from "@/lib/utils";
import { useNow } from "../hooks/use-now";
import { resolveLocale, toDate } from "../../comment-thread/lib/format-time";
import type { PostPoll, PostPollOption } from "../types";

export interface PollWidgetProps {
  poll: PostPoll;
  /**
   * Whether the viewer has already cast a vote. Resolved from local-mirror
   * (optimistic, takes precedence) OR `poll.hasVoted` (server-resolved).
   * When true, the results view renders instead of vote buttons.
   */
  hasVoted: boolean;
  /**
   * Owner-side view — always shows results, never the vote buttons (owners
   * don't vote on their own polls).
   */
  isOwnerView: boolean;
  /**
   * The option id the viewer voted for (highlights in results view). When
   * sourced from the local mirror, the optimistic increment is applied to
   * that option's display count.
   */
  optimisticVoteOptionId?: string;
  /**
   * Whether the optimistic-vote increment should bump the displayed counts.
   * `true` when `optimisticVoteOptionId` came from the in-card local mirror
   * (the host hasn't reconciled yet). `false` when sourced from
   * `poll.viewerVoteOptionId` (server-resolved; counts already reflect it).
   */
  optimisticIncrement: boolean;
  /** Fires when the viewer taps a vote button. */
  onVote?: (optionId: string) => void;
  labels: {
    pollHeading: string;
    /** `formatted` is the count in the card's locale. */
    pollTotalVotesLabel: (count: number, formatted: string) => string;
    pollClosesAtLabel: (time: string) => string;
    pollClosedLabel: string;
  };
  /** Relative-time formatter for the closesAt countdown. */
  formatRelativeTime?: (date: Date, now: Date) => string;
  /** Count formatter for the total. Default: the plain number. */
  formatCount?: (n: number) => string;
  /**
   * "Now" for the closed check and the countdown. Without it the widget reads the clock after
   * mount (before that the poll counts as open and shows no countdown).
   */
  now?: Date;
  /** BCP 47 locale of the percentages. Default "en". */
  locale?: string;
  /**
   * A vote is in flight: the vote buttons stay (`aria-disabled`) and ignore taps, so a second tap
   * cannot send a second vote.
   */
  busy?: boolean;
  className?: string;
}

function clampPct(n: number): number {
  if (!Number.isFinite(n) || n <= 0) return 0;
  if (n >= 100) return 100;
  return n;
}

interface ResolvedOption extends PostPollOption {
  pct: number;
  isViewerChoice: boolean;
}

/**
 * Sealed client component rendering the inline poll widget. Two views:
 *   - **Vote view** (viewer + not voted + not closed) — list of vote buttons,
 *     min h-11 per WCAG 2.5.5 (Q-P40).
 *   - **Results view** (owner OR voted OR closed) — bar chart with width
 *     transition (Q-P17 / Q-P41 motion-reduce safe). Viewer's option is
 *     highlighted via accent ring.
 *
 * Optimistic vote: the card applies the vote to the shown post itself and passes
 * `optimisticIncrement={false}`; `optimisticIncrement` remains for standalone use, where
 * the caller wants the picked option's count + the total bumped by one.
 *
 * Multi-select polls are not supported — single-vote
 * behavior renders regardless of `poll.multiSelect` (not implemented).
 * (additive when added).
 */
export function PollWidget({
  poll,
  hasVoted,
  isOwnerView,
  optimisticVoteOptionId,
  optimisticIncrement,
  onVote,
  labels,
  formatRelativeTime,
  formatCount,
  now: nowProp,
  locale,
  busy = false,
  className,
}: PollWidgetProps) {
  const now = useNow(nowProp);
  const percent = useMemo(
    () => new Intl.NumberFormat(resolveLocale(locale), { style: "percent", maximumFractionDigits: 0 }),
    [locale],
  );
  const closesDate = poll.closesAt ? toDate(poll.closesAt) : undefined;
  const isClosed = !!(closesDate && now && closesDate.getTime() <= now.getTime());
  const showResults = isOwnerView || hasVoted || isClosed;

  // Tapping a vote button unmounts it when the view flips to the results; focus moves to the
  // poll group (a programmatic target only) instead of falling to <body>.
  const groupRef = useRef<HTMLDivElement>(null);
  const refocus = useRef(false);
  useEffect(() => {
    if (showResults) {
      if (refocus.current) {
        refocus.current = false;
        groupRef.current?.focus();
      }
    } else if (!busy) {
      refocus.current = false;
    }
  }, [showResults, busy]);

  const { resolvedOptions, displayedTotal } = useMemo(() => {
    const bumpedTotal =
      poll.totalVotes + (optimisticVoteOptionId && optimisticIncrement ? 1 : 0);
    const safeTotal = bumpedTotal > 0 ? bumpedTotal : 1;
    const resolved: ResolvedOption[] = poll.options.map((opt) => {
      const isViewerChoice = opt.id === optimisticVoteOptionId;
      const bumpedCount =
        isViewerChoice && optimisticIncrement
          ? opt.voteCount + 1
          : opt.voteCount;
      return {
        ...opt,
        voteCount: bumpedCount,
        isViewerChoice,
        pct: clampPct((bumpedCount / safeTotal) * 100),
      };
    });
    return { resolvedOptions: resolved, displayedTotal: bumpedTotal };
  }, [poll, optimisticVoteOptionId, optimisticIncrement]);

  // Closes-at line. Needs "now": before it is known (the server and the first client render)
  // the poll counts as open and shows no countdown.
  let closesAtLine: string | undefined;
  if (isClosed) {
    closesAtLine = labels.pollClosedLabel;
  } else if (closesDate && now && formatRelativeTime) {
    closesAtLine = labels.pollClosesAtLabel(formatRelativeTime(closesDate, now));
  }

  const totalVotesLine = labels.pollTotalVotesLabel(
    displayedTotal,
    formatCount ? formatCount(displayedTotal) : String(displayedTotal),
  );

  return (
    <div
      className={cn(
        "flex flex-col gap-2 rounded-lg border border-border bg-card p-3",
        className,
      )}
      role="group"
      aria-label={labels.pollHeading}
      ref={groupRef}
      tabIndex={-1}
    >
      <div className="flex items-center justify-between gap-2 text-xs text-muted-foreground">
        <span className="font-semibold text-foreground">{labels.pollHeading}</span>
        <span className="flex items-center gap-2">
          <span>{totalVotesLine}</span>
          {closesAtLine ? <span aria-hidden="true">·</span> : null}
          {closesAtLine ? <span>{closesAtLine}</span> : null}
        </span>
      </div>

      {showResults ? (
        <ul className="flex flex-col gap-2">
          {resolvedOptions.map((opt) => (
            <li key={opt.id} className="relative">
              <div
                className={cn(
                  "relative flex items-center justify-between gap-2 overflow-hidden rounded-md border border-border bg-muted/30 px-3 py-2 text-sm",
                  opt.isViewerChoice && "ring-1 ring-primary",
                )}
              >
                <div
                  aria-hidden="true"
                  className={cn(
                    "absolute inset-y-0 start-0 transition-[width] duration-300 ease-out motion-reduce:transition-none",
                    opt.isViewerChoice ? "bg-primary/20" : "bg-foreground/[0.06]",
                  )}
                  style={{ width: `${opt.pct}%` }}
                />
                <span className="relative min-w-0 truncate font-medium">
                  {opt.label}
                </span>
                <span className="relative shrink-0 tabular-nums text-xs text-muted-foreground">
                  {percent.format(opt.pct / 100)}
                </span>
              </div>
            </li>
          ))}
        </ul>
      ) : (
        <ul className="flex flex-col gap-2">
          {resolvedOptions.map((opt) => (
            <li key={opt.id}>
              <button
                type="button"
                onClick={
                  onVote
                    ? () => {
                        if (busy) return;
                        refocus.current = true;
                        onVote(opt.id);
                      }
                    : undefined
                }
                disabled={!onVote}
                aria-disabled={busy ? true : undefined}
                className={cn(
                  "flex h-11 w-full items-center justify-start rounded-md border border-border bg-background px-3 text-sm font-medium",
                  "transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
                  "disabled:cursor-not-allowed disabled:opacity-60 aria-disabled:cursor-not-allowed aria-disabled:opacity-60",
                  "focus:outline-none",
                )}
              >
                <span className="min-w-0 truncate">{opt.label}</span>
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

