import {
  BarChart3,
  Bookmark,
  Copy,
  EyeOff,
  Flag,
  Globe,
  Languages,
  Pencil,
  Pin,
  PinOff,
  Share2,
  ShieldAlert,
  Trash2,
  UserX,
  VolumeX,
} from "lucide-react";
// F-S1 lock: cross-procomp imports via relative + specific-file paths.
import type { EngagementAction } from "../../engagement-bar/types";
import type { CommentMenuItem } from "../../comment-thread/types";
import type {
  Post,
  PostCardLabels,
  PostCardVariant,
  PostHandlers,
  PostMutationHandlers,
  PostPermissionAction,
  PostPermissions,
  PostReactions,
  PostViewerMode,
} from "../types";
import {
  canPerformActionInternal,
  resolvePostPermissions,
} from "./permissions";

export function defaultPostEngagementActions(
  post: Post,
  handlers: PostHandlers,
  variant: PostCardVariant,
  /**
   * Optional separate handler for the like-count tap target. When provided, the
   * heart icon stays on `onToggle` and the count text becomes its own button
   * firing `onCountClick` (kasder UX — heart toggles like, count opens likers panel).
   */
  onLikeCountClick?: () => void,
  /**
   * With reactions, a `kind: "reaction"` action takes the place of the like: `counts` merge into
   * the kinds' tallies, `viewerReaction` / `totalCount` / `clearOnTap` pass through and a pick
   * calls `reactions.onReact(post.id, kind)`.
   */
  reactions?: PostReactions,
): EngagementAction[] {
  const like: EngagementAction = reactions
    ? {
        kind: "reaction",
        kinds: reactions.kinds.map((k) => {
          const tally = reactions.counts?.[k.key];
          return tally === undefined ? k : { ...k, count: tally };
        }),
        totalCount: reactions.totalCount,
        viewerReaction: reactions.viewerReaction,
        clearOnTap: reactions.clearOnTap,
        onSelect: reactions.onReact
          ? (kind) => reactions.onReact!(post.id, kind)
          : undefined,
        onCountClick: onLikeCountClick,
      }
    : {
        kind: "like",
        count: post.likes,
        liked: post.isLiked ?? false,
        onToggle: handlers.onLike
          ? (next) => {
              handlers.onLike!(post.id, next);
            }
          : undefined,
        onCountClick: onLikeCountClick,
      };

  const comment: EngagementAction = {
    kind: "comment",
    count: post.comments,
    onClick: handlers.onComment
      ? () => handlers.onComment!(post.id)
      : undefined,
  };

  if (variant === "compact") {
    return [like, comment];
  }

  if (variant === "list") {
    // List variant default: counts only — interactive bar opt-in via slot.
    return [];
  }

  // feed + detail
  const actions: EngagementAction[] = [
    like,
    comment,
    {
      kind: "share",
      count: post.shares,
      onClick: handlers.onShare ? () => handlers.onShare!(post.id) : undefined,
    },
    {
      kind: "bookmark",
      bookmarked: post.isBookmarked ?? false,
      onToggle: handlers.onBookmark
        ? (next) => handlers.onBookmark!(post.id, next)
        : undefined,
    },
  ];
  if (variant === "detail" && post.viewCount !== undefined) {
    actions.push({ kind: "view-count", count: post.viewCount });
  }
  return actions;
}

/**
 * Default kebab item builder. Dual-mode helper:
 *
 *   - **Legacy mode (v0.1 backwards-compat):** when `viewerMode` / `permissions` /
 *     `canPerformAction` are ALL `undefined`, the helper takes the exact v0.1
 *     handler-driven code path. Items are built from "which handler is wired."
 *     Zero behavior drift for v0.1 consumers.
 *
 *   - **Role-aware mode (v0.2.0):** when ANY of the three role-aware args is set,
 *     the helper calls `resolvePostPermissions` + `canPerformActionInternal` to
 *     produce role-appropriate items per the resolution order in plan §3.
 *     Owner mode shows Edit / Delete / Pin / Change-visibility / Mark-sensitive /
 *     See-analytics; viewer mode shows Report / Block author / Mute author;
 *     common actions (Bookmark / Share / Copy link / Translate) gated by the
 *     resolved matrix.
 *
 * Backwards-compat: trailing args (`viewerMode`, `permissions`, `canPerformAction`,
 * `mutationHandlers`, `onTranslate`) are all optional. Old v0.1 call sites
 * compile unchanged.
 */
export function defaultPostKebabActions(
  post: Post,
  handlers: {
    onBookmark?: PostHandlers["onBookmark"];
    onShare?: PostHandlers["onShare"];
    onReport?: (postId: string) => void;
    onCopyLink?: (postId: string) => void;
  },
  labels: Required<
    Pick<
      PostCardLabels,
      "bookmark" | "unbookmark" | "share" | "copyLink" | "report"
    >
  > &
    Partial<
      Pick<
        PostCardLabels,
        | "edit"
        | "delete"
        | "pin"
        | "unpin"
        | "changeVisibility"
        | "markSensitive"
        | "unmarkSensitive"
        | "seeAnalytics"
        | "blockAuthor"
        | "muteAuthor"
        | "translate"
      >
    >,
  viewerMode?: PostViewerMode,
  permissions?: PostPermissions,
  canPerformAction?: (
    action: PostPermissionAction,
    post: Post,
  ) => boolean | undefined,
  mutationHandlers?: Partial<PostMutationHandlers>,
  onTranslate?: (postId: string, sourceLanguage: string) => void,
  /**
   * v0.3.0 — supplier for the moderator section. Items render between common
   * items and viewer-destructive items, with `separatorBefore: true` injected
   * on the first item so the host kebab renders a divider above the group.
   * Gated by `canDo("moderate")` — host opts the viewer in via
   * `permissions.canModerate` or `canPerformAction("moderate", post)`.
   */
  moderatorActions?: (post: Post) => CommentMenuItem[],
  /**
   * 0.6.0 - items appended after every default item (after the destructive group, not gated by
   * `canModerate`), in both modes. `hidden` items are left out later, by the menu.
   */
  extraItems?: CommentMenuItem[],
): CommentMenuItem[] {
  // `permissions` that only carries `disabled` does not switch on role-aware mode: the legacy
  // handler-driven items stay, with the named ones disabled.
  const permissionsOnlyDisables =
    permissions !== undefined &&
    permissions.disabled !== undefined &&
    (Object.keys(permissions) as (keyof PostPermissions)[]).every(
      (k) => k === "disabled" || permissions[k] === undefined,
    );
  const roleAwareMode =
    viewerMode !== undefined ||
    (permissions !== undefined && !permissionsOnlyDisables) ||
    canPerformAction !== undefined;
  const isDisabled = (action: PostPermissionAction) =>
    permissions?.disabled?.[action] === true;
  const withExtras = (items: CommentMenuItem[]) =>
    extraItems && extraItems.length > 0 ? [...items, ...extraItems] : items;

  // ─── Legacy mode (v0.1 path) ─── unchanged behavior; resolver NOT called
  if (!roleAwareMode) {
    const items: CommentMenuItem[] = [];
    if (handlers.onBookmark) {
      items.push({
        label: post.isBookmarked ? labels.unbookmark : labels.bookmark,
        icon: <Bookmark className="h-4 w-4" />,
        disabled: isDisabled("bookmark") || undefined,
        onClick: () =>
          handlers.onBookmark!(post.id, !(post.isBookmarked ?? false)),
      });
    }
    if (handlers.onShare) {
      items.push({
        label: labels.share,
        icon: <Share2 className="h-4 w-4" />,
        disabled: isDisabled("share") || undefined,
        onClick: () => handlers.onShare!(post.id),
      });
    }
    if (handlers.onCopyLink) {
      items.push({
        label: labels.copyLink,
        icon: <Copy className="h-4 w-4" />,
        onClick: () => handlers.onCopyLink!(post.id),
      });
    }
    if (handlers.onReport) {
      items.push({
        label: labels.report,
        icon: <Flag className="h-4 w-4" />,
        destructive: true,
        disabled: isDisabled("report") || undefined,
        onClick: () => handlers.onReport!(post.id),
      });
    }
    return withExtras(items);
  }

  // ─── Role-aware mode (v0.2.0) ─── resolve matrix + assemble items per resolution order
  const matrix = resolvePostPermissions(viewerMode, permissions);
  const canDo = (action: PostPermissionAction) =>
    canPerformActionInternal(action, post, matrix, canPerformAction);
  const items: CommentMenuItem[] = [];

  // Owner-side items — only shown when matrix allows AND handler is wired
  if (canDo("edit") && mutationHandlers?.onEdit) {
    items.push({
      label: labels.edit ?? "Edit",
      icon: <Pencil className="h-4 w-4" />,
      disabled: isDisabled("edit") || undefined,
      onClick: () => mutationHandlers.onEdit!(post.id),
    });
  }
  if (canDo("pin") && mutationHandlers?.onPin) {
    items.push({
      label: post.isPinned ? (labels.unpin ?? "Unpin") : (labels.pin ?? "Pin to top"),
      icon: post.isPinned ? <PinOff className="h-4 w-4" /> : <Pin className="h-4 w-4" />,
      disabled: isDisabled("pin") || undefined,
      onClick: () => mutationHandlers.onPin!(post.id, !(post.isPinned ?? false)),
    });
  }
  if (canDo("changeVisibility") && mutationHandlers?.onChangeVisibility) {
    items.push({
      label: labels.changeVisibility ?? "Change visibility",
      icon: <Globe className="h-4 w-4" />,
      disabled: isDisabled("changeVisibility") || undefined,
      onClick: () => mutationHandlers.onChangeVisibility!(post.id, post.visibility),
    });
  }
  if (canDo("markSensitive") && mutationHandlers?.onMarkSensitive) {
    items.push({
      label: post.isSensitive
        ? (labels.unmarkSensitive ?? "Remove sensitive mark")
        : (labels.markSensitive ?? "Mark as sensitive"),
      icon: post.isSensitive ? <EyeOff className="h-4 w-4" /> : <ShieldAlert className="h-4 w-4" />,
      disabled: isDisabled("markSensitive") || undefined,
      onClick: () =>
        mutationHandlers.onMarkSensitive!(post.id, !(post.isSensitive ?? false)),
    });
  }
  if (canDo("seeAnalytics") && mutationHandlers?.onSeeAnalytics) {
    items.push({
      label: labels.seeAnalytics ?? "See analytics",
      icon: <BarChart3 className="h-4 w-4" />,
      disabled: isDisabled("seeAnalytics") || undefined,
      onClick: () => mutationHandlers.onSeeAnalytics!(post.id),
    });
  }

  // Common items (host-policy gated) — Bookmark / Share / Copy link
  if (canDo("bookmark") && handlers.onBookmark) {
    items.push({
      label: post.isBookmarked ? labels.unbookmark : labels.bookmark,
      icon: <Bookmark className="h-4 w-4" />,
      disabled: isDisabled("bookmark") || undefined,
      onClick: () =>
        handlers.onBookmark!(post.id, !(post.isBookmarked ?? false)),
    });
  }
  if (canDo("share") && handlers.onShare) {
    items.push({
      label: labels.share,
      icon: <Share2 className="h-4 w-4" />,
      disabled: isDisabled("share") || undefined,
      onClick: () => handlers.onShare!(post.id),
    });
  }
  if (handlers.onCopyLink) {
    items.push({
      label: labels.copyLink,
      icon: <Copy className="h-4 w-4" />,
      onClick: () => handlers.onCopyLink!(post.id),
    });
  }

  // Translate (gated by post.language presence + handler) — not a canX matrix action
  if (post.language && onTranslate) {
    items.push({
      label: labels.translate ?? "Translate",
      icon: <Languages className="h-4 w-4" />,
      onClick: () => onTranslate(post.id, post.language!),
    });
  }

  // ─── v0.3.0 moderator section ─── ILX-3
  // Rendered between common items and viewer-destructive items. Gated by
  // `canDo("moderate")` AND a non-empty `moderatorActions(post)` return.
  // The first moderator item carries `separatorBefore: true` so the host
  // kebab renders a divider above the whole group.
  if (canDo("moderate") && moderatorActions) {
    const modItems = moderatorActions(post).map((m) =>
      isDisabled("moderate") ? { ...m, disabled: true } : m,
    );
    if (modItems.length > 0) {
      items.push({ ...modItems[0], separatorBefore: true });
      for (let i = 1; i < modItems.length; i++) {
        items.push(modItems[i]);
      }
    }
  }

  // Viewer-side items (destructive at the bottom)
  if (canDo("muteAuthor") && mutationHandlers?.onMuteAuthor) {
    items.push({
      label: labels.muteAuthor ?? "Mute author",
      icon: <VolumeX className="h-4 w-4" />,
      disabled: isDisabled("muteAuthor") || undefined,
      onClick: () => mutationHandlers.onMuteAuthor!(post.author.id),
    });
  }
  if (canDo("blockAuthor") && mutationHandlers?.onBlockAuthor) {
    items.push({
      label: labels.blockAuthor ?? "Block author",
      icon: <UserX className="h-4 w-4" />,
      disabled: isDisabled("blockAuthor") || undefined,
      destructive: true,
      onClick: () => mutationHandlers.onBlockAuthor!(post.author.id),
    });
  }
  if (canDo("report") && handlers.onReport) {
    items.push({
      label: labels.report,
      icon: <Flag className="h-4 w-4" />,
      destructive: true,
      disabled: isDisabled("report") || undefined,
      onClick: () => handlers.onReport!(post.id),
    });
  }

  // Owner-side destructive (last) — Delete
  if (canDo("delete") && mutationHandlers?.onDelete) {
    items.push({
      label: labels.delete ?? "Delete",
      icon: <Trash2 className="h-4 w-4" />,
      disabled: isDisabled("delete") || undefined,
      destructive: true,
      onClick: () => mutationHandlers.onDelete!(post.id),
    });
  }

  return withExtras(items);
}

/**
 * Pure permission resolver for post-card v0.2.0.
 *
 * Resolution order (most → least specific) per plan §3:
 *   1. `canPerformAction(action, post)` returning `true | false` — wins everything for that action
 *   2. `permissions[canX]` per-field — `false` denies, `true` allows
 *   3. `viewerMode`-derived defaults from `PERMISSION_DEFAULTS_BY_MODE`
 *   4. Library-baseline default (legacy mode — caller must short-circuit before
 *      calling this resolver; see `defaultPostKebabActions` dual-mode branch)
 *
 * Truth table:
 * | viewerMode  | permissions  | resolved matrix                                    |
 * |-------------|--------------|----------------------------------------------------|
 * | `undefined` | `undefined`  | (resolver NOT called — legacy v0.1 path)           |
 * | `undefined` | `{ ... }`    | viewer baseline + permissions override per-field   |
 * | `"owner"`   | `undefined`  | owner defaults (all owner-side true)               |
 * | `"owner"`   | `{ ... }`    | owner defaults + permissions override per-field    |
 * | `"viewer"`  | `undefined`  | viewer defaults (viewer-side true, owner-side false) |
 * | `"viewer"`  | `{ ... }`    | viewer defaults + permissions override per-field   |
 */

import type {
  Post,
  PostPermissionAction,
  PostPermissions,
  PostViewerMode,
} from "../types";

/**
 * Library-baseline permission matrix by viewer mode. `Required<PostPermissions>`
 * ensures every field is resolved (no `undefined` leaks downstream).
 *
 * `canShare` + `canBookmark` default to `true` in both modes — host-policy gates
 * (the host can deny by setting `permissions={{ canShare: false }}` for visibility-restricted posts).
 */
export const PERMISSION_DEFAULTS_BY_MODE: Record<
  PostViewerMode,
  Required<PostPermissions>
> = {
  owner: {
    canEdit: true,
    canDelete: true,
    canPin: true,
    canChangeVisibility: true,
    canMarkSensitive: true,
    canSeeAnalytics: true,
    canShare: true,
    canBookmark: true,
    canReport: false,
    canBlockAuthor: false,
    canMuteAuthor: false,
    // moderation is orthogonal to viewerMode — never auto-derived; host opts in
    // explicitly via permissions.canModerate or canPerformAction("moderate", …).
    canModerate: false,
    disabled: {},
  },
  viewer: {
    canEdit: false,
    canDelete: false,
    canPin: false,
    canChangeVisibility: false,
    canMarkSensitive: false,
    canSeeAnalytics: false,
    canShare: true,
    canBookmark: true,
    canReport: true,
    canBlockAuthor: true,
    canMuteAuthor: true,
    canModerate: false,
    disabled: {},
  },
};

/**
 * Map a `PostPermissionAction` string to its `PostPermissions` matrix key.
 *
 * `"edit"` → `"canEdit"`, `"changeVisibility"` → `"canChangeVisibility"`, etc.
 * Pure, no side effects. Used by `canPerformActionInternal` to look up the
 * matrix value for a given action.
 */
function actionToPermissionKey(
  action: PostPermissionAction,
): keyof PostPermissions {
  return `can${action.charAt(0).toUpperCase()}${action.slice(1)}` as keyof PostPermissions;
}

/**
 * Pure resolver — returns the fully-resolved permission matrix for the
 * rendering pass. Does NOT consult `canPerformAction` (that's evaluated
 * per-action by `canPerformActionInternal`).
 *
 * Caller's contract: only invoke when role-aware mode is active (at least one
 * of `viewerMode` / `permissions` / `canPerformAction` is set). Legacy mode
 * short-circuits in the calling helper before this is reached.
 */
export function resolvePostPermissions(
  viewerMode: PostViewerMode | undefined,
  permissions: PostPermissions | undefined,
): Required<PostPermissions> {
  const base = viewerMode
    ? PERMISSION_DEFAULTS_BY_MODE[viewerMode]
    : PERMISSION_DEFAULTS_BY_MODE.viewer; // viewer baseline when viewerMode undefined but permissions set
  if (!permissions) return { ...base };
  // Skip undefined fields during merge: `permissions={{ canEdit: undefined }}`
  // should fall through to the mode default, not override it with undefined.
  // Required<PostPermissions> contract: every returned field is a definite boolean.
  const result: Required<PostPermissions> = { ...base };
  for (const key of Object.keys(permissions) as (keyof PostPermissions)[]) {
    if (key === "disabled") continue;
    const value = permissions[key];
    if (value !== undefined) {
      result[key] = value;
    }
  }
  // `disabled` is additive: it never changes whether an action is allowed, only whether its
  // item is usable.
  result.disabled = { ...permissions.disabled };
  return result;
}

/**
 * Per-action resolution. Returns `true` to allow the action / `false` to deny.
 *
 * Resolution per plan §3:
 *   1. `canPerformAction(action, post)` returning `true | false` wins
 *   2. Matrix value from `resolvedMatrix` (already includes mode defaults + permissions overrides)
 *
 * `canPerformAction` returning `undefined` falls through to step 2.
 */
export function canPerformActionInternal(
  action: PostPermissionAction,
  post: Post,
  resolvedMatrix: Required<PostPermissions>,
  canPerformAction:
    | ((action: PostPermissionAction, post: Post) => boolean | undefined)
    | undefined,
): boolean {
  if (canPerformAction) {
    const result = canPerformAction(action, post);
    if (result !== undefined) return result;
  }
  return resolvedMatrix[actionToPermissionKey(action)] !== false;
}

import { useCallback, useMemo, useRef, useSyncExternalStore } from "react";

const MINUTE_MS = 60_000;

/**
 * "Now" for relative times, safe for server rendering.
 * - `nowProp` given: returned as is, no timer.
 * - Otherwise `null` while rendering on the server and on the first client render (the caller
 *   prints no relative text, so the two agree), then the clock read right after mount and again
 *   every 60 s. Re-rendering never reads the clock: the value only moves on the tick.
 */
export function useNow(nowProp: Date | undefined): Date | null {
  const hasNowProp = nowProp !== undefined;
  const clock = useRef<number | null>(null);
  const subscribe = useCallback(
    (notify: () => void) => {
      if (hasNowProp) return () => {};
      clock.current = Date.now();
      const id = setInterval(() => {
        clock.current = Date.now();
        notify();
      }, MINUTE_MS);
      return () => clearInterval(id);
    },
    [hasNowProp],
  );
  const read = useCallback((): number | null => clock.current, []);
  const readServer = useCallback((): number | null => null, []);
  const ms = useSyncExternalStore(subscribe, read, readServer);
  return useMemo(() => nowProp ?? (ms === null ? null : new Date(ms)), [nowProp, ms]);
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { EngagementDelta } from "../../engagement-bar/types";
import type { Post, PostChange } from "../types";

type Slot = "like" | "bookmark" | "vote";
/** An in-flight change, bound to the post it was made on. */
type Overlay = Partial<Record<Slot, { apply: (post: Post) => Post; postId: string | null }>>;

/** Idempotent: setting the state a post already has changes nothing. */
export function applyLike(post: Post, liked: boolean): Post {
  if ((post.isLiked ?? false) === liked) return post;
  return { ...post, isLiked: liked, likes: liked ? post.likes + 1 : Math.max(0, post.likes - 1) };
}

export function applyBookmark(post: Post, bookmarked: boolean): Post {
  if ((post.isBookmarked ?? false) === bookmarked) return post;
  return { ...post, isBookmarked: bookmarked };
}

/** Records the viewer's vote on the poll. A poll the viewer already voted on is left as is. */
export function applyVote(post: Post, optionId: string): Post {
  const poll = post.poll;
  if (!poll || poll.hasVoted || poll.viewerVoteOptionId !== undefined) return post;
  return {
    ...post,
    poll: {
      ...poll,
      hasVoted: true,
      viewerVoteOptionId: optionId,
      totalVotes: poll.totalVotes + 1,
      options: poll.options.map((o) => (o.id === optionId ? { ...o, voteCount: o.voteCount + 1 } : o)),
    },
  };
}

/**
 * Folds a realtime engagement delta into the post. A delta the post has no field for, or one that
 * equals what the post already shows (an echo), returns the post itself.
 */
export function applyDelta(post: Post, delta: EngagementDelta): Post {
  switch (delta.kind) {
    case "like-changed": {
      const liked = delta.liked ?? post.isLiked;
      if (post.likes === delta.count && (post.isLiked ?? false) === (liked ?? false)) return post;
      return { ...post, likes: delta.count, isLiked: liked };
    }
    case "bookmark-changed":
      return (post.isBookmarked ?? false) === delta.bookmarked ? post : { ...post, isBookmarked: delta.bookmarked };
    case "comment-count-changed":
      return post.comments === delta.count ? post : { ...post, comments: delta.count };
    case "share-count-changed":
      return post.shares === delta.count ? post : { ...post, shares: delta.count };
    case "view-count-changed":
      return post.viewCount === delta.count ? post : { ...post, viewCount: delta.count };
    default:
      return post;
  }
}

function isThenable(value: unknown): value is Promise<unknown> {
  return !!value && typeof (value as { then?: unknown }).then === "function";
}

export interface UsePostStateOptions {
  post: Post;
  /** Makes `post` controlled. */
  onPostChange?: (next: Post, change: PostChange) => void;
  /** Show a change while its promise is in flight. Default `true`. */
  optimistic?: boolean;
}

export interface PostState {
  /** The post to render: the prop (controlled) or the local mirror, with in-flight changes over it. */
  shown: Post;
  /** Request a like. `call` runs the host's handler; return its promise (if any). */
  like: (next: boolean, call: () => void | Promise<unknown>) => void;
  bookmark: (next: boolean, call: () => void | Promise<unknown>) => void;
  vote: (optionId: string, call: () => void | Promise<unknown>) => void;
  /** A realtime delta: applied to the mirror (uncontrolled) or reported (controlled). */
  delta: (delta: EngagementDelta) => void;
  /** Drop every in-flight change and (uncontrolled) replace the mirror. */
  reset: (next: Post) => void;
  /** A poll vote is in flight: further votes are ignored until it settles. */
  voting: boolean;
}

/**
 * The card's post state (consumer contract C5).
 * - Uncontrolled (no `onPostChange`): the first `post` seeds a local mirror. A change applies at
 *   once (a handler that returns nothing) or while its promise is in flight (`optimistic`) and
 *   sticks when it resolves; a rejection drops it.
 * - Controlled (`onPostChange`): `post` wins every render. A change is an overlay while its
 *   promise is in flight and is never applied: once accepted it is reported with the next post.
 * Only the latest request per slot decides the overlay; an older request that settles after a
 * newer one was accepted is not reported. Controlled reports build on a synchronous "working"
 * post that every report advances, so two changes accepted before React commits both land. A
 * change that alters nothing is not reported. A new `post.id` drops everything in flight.
 */
export function usePostState({ post, onPostChange, optimistic = true }: UsePostStateOptions): PostState {
  const controlled = onPostChange !== undefined;
  const [mirror, setMirror] = useState<Post>(post);
  const [overlay, setOverlay] = useState<Overlay>({});
  const [voting, setVoting] = useState(false);
  const base = controlled ? post : mirror;

  // A different post in controlled mode: whatever was in flight belonged to the old one.
  const [seenId, setSeenId] = useState(post.id);
  if (controlled && seenId !== post.id) {
    setSeenId(post.id);
    setOverlay({});
    setVoting(false);
  }

  const shown = useMemo(() => {
    let out = base;
    for (const slot of ["like", "bookmark", "vote"] as const) {
      const entry = overlay[slot];
      if (entry && (entry.postId === null || entry.postId === base.id)) out = entry.apply(out);
    }
    return out;
  }, [base, overlay]);

  const propRef = useRef(post);
  /** The post controlled reports build on: the prop, advanced by every report since it last changed. */
  const workingRef = useRef(post);
  const controlledRef = useRef(controlled);
  const onPostChangeRef = useRef(onPostChange);
  const optimisticRef = useRef(optimistic);
  const voteInFlight = useRef(false);
  const seq = useRef<Record<Slot, number>>({ like: 0, bookmark: 0, vote: 0 });
  const accepted = useRef<Record<Slot, number>>({ like: 0, bookmark: 0, vote: 0 });
  const epoch = useRef(0);
  useEffect(() => {
    controlledRef.current = controlled;
    onPostChangeRef.current = onPostChange;
    optimisticRef.current = optimistic;
  });
  useEffect(() => {
    propRef.current = post;
    workingRef.current = post;
  }, [post]);
  const resyncTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  useEffect(() => () => clearTimeout(resyncTimer.current), []);
  /**
   * Advance the working post after a report. A host that does not adopt the change leaves the prop
   * as it was, so the working post falls back to the prop once the task is over (otherwise a
   * second request for the same change would be swallowed as a no-op).
   */
  const advance = useCallback((next: Post) => {
    workingRef.current = next;
    clearTimeout(resyncTimer.current);
    resyncTimer.current = setTimeout(() => {
      workingRef.current = propRef.current;
    }, 0);
  }, []);
  const lastId = useRef(post.id);
  useEffect(() => {
    if (!controlled || lastId.current === post.id) return;
    lastId.current = post.id;
    epoch.current += 1;
    voteInFlight.current = false;
  }, [controlled, post.id]);

  const clearSlot = useCallback((slot: Slot) => {
    setOverlay((o) => {
      if (!o[slot]) return o;
      const next = { ...o };
      delete next[slot];
      return next;
    });
  }, []);

  const run = useCallback(
    (slot: Slot, apply: (post: Post) => Post, change: PostChange, call: () => void | Promise<unknown>) => {
      if (slot === "vote" && voteInFlight.current) return;
      const id = ++seq.current[slot];
      const startEpoch = epoch.current;
      const wasControlled = controlledRef.current;
      const startPostId = wasControlled ? workingRef.current.id : "";
      const result = call();

      const accept = () => {
        if (startEpoch !== epoch.current || id <= accepted.current[slot]) return;
        accepted.current[slot] = id;
        if (wasControlled) {
          const current = workingRef.current;
          if (current.id !== startPostId) return;
          const next = apply(current);
          if (next === current) return;
          advance(next);
          onPostChangeRef.current?.(next, change);
        } else {
          setMirror((m) => apply(m));
        }
      };

      if (!isThenable(result)) {
        accept();
        clearSlot(slot);
        return;
      }
      if (slot === "vote") {
        voteInFlight.current = true;
        setVoting(true);
      }
      if (optimisticRef.current) {
        setOverlay((o) => ({ ...o, [slot]: { apply, postId: wasControlled ? startPostId : null } }));
      }
      const settle = () => {
        if (startEpoch !== epoch.current) return;
        if (slot === "vote") {
          voteInFlight.current = false;
          setVoting(false);
        }
        if (id === seq.current[slot]) clearSlot(slot);
      };
      result.then(
        () => {
          accept();
          settle();
        },
        settle,
      );
    },
    [clearSlot, advance],
  );

  const like = useCallback(
    (next: boolean, call: () => void | Promise<unknown>) =>
      run("like", (p) => applyLike(p, next), { kind: "like", liked: next }, call),
    [run],
  );
  const bookmark = useCallback(
    (next: boolean, call: () => void | Promise<unknown>) =>
      run("bookmark", (p) => applyBookmark(p, next), { kind: "bookmark", bookmarked: next }, call),
    [run],
  );
  const vote = useCallback(
    (optionId: string, call: () => void | Promise<unknown>) =>
      run("vote", (p) => applyVote(p, optionId), { kind: "poll-vote", optionId }, call),
    [run],
  );

  const delta = useCallback((d: EngagementDelta) => {
    if (controlledRef.current) {
      const current = workingRef.current;
      const next = applyDelta(current, d);
      if (next === current) return;
      advance(next);
      onPostChangeRef.current?.(next, { kind: "delta", delta: d });
    } else {
      setMirror((m) => applyDelta(m, d));
    }
  }, [advance]);

  const reset = useCallback((next: Post) => {
    epoch.current += 1;
    voteInFlight.current = false;
    workingRef.current = propRef.current;
    setVoting(false);
    setMirror(next);
    setOverlay({});
  }, []);

  return { shown, like, bookmark, vote, delta, reset, voting };
}

import {
  defaultPostCardLabels,
  type PostCardLabels,
  type PostCardNestedLabelKeys,
  type ResolvedPostCardLabels,
} from "../types";

const NESTED: ReadonlySet<string> = new Set<PostCardNestedLabelKeys>([
  "formatRelativeTime",
  "engagementLabels",
  "commentLabels",
  "likersLabels",
  "shareLabels",
  "textLabels",
]);

/**
 * Merge a partial `labels` over the defaults; an explicit `undefined` keeps the default. The
 * nested and deprecated keys are left out (the parts that own them read them from `labels`).
 * A function-valued label must be a function: anything else keeps the default and is reported
 * to `onInvalid(key)`.
 */
export function resolveLabels(
  labels: PostCardLabels | undefined,
  onInvalid?: (key: string) => void,
): ResolvedPostCardLabels {
  const out: ResolvedPostCardLabels = { ...defaultPostCardLabels };
  if (!labels) return out;
  const target = out as unknown as Record<string, unknown>;
  const defaults = defaultPostCardLabels as unknown as Record<string, unknown>;
  for (const [key, value] of Object.entries(labels)) {
    if (value === undefined || NESTED.has(key)) continue;
    if (typeof defaults[key] === "function" && typeof value !== "function") {
      onInvalid?.(key);
      continue;
    }
    target[key] = value;
  }
  return out;
}

/** `{ ...base, ...over }` that skips `undefined` values in `over` (an explicit `undefined` keeps the base). */
export function mergeLabels<T extends object>(base: T, over: Partial<T> | undefined): T {
  if (!over) return base;
  const out = { ...base } as Record<string, unknown>;
  for (const [key, value] of Object.entries(over)) {
    if (value !== undefined) out[key] = value;
  }
  return out as T;
}

import type { ReactNode } from "react";
// Cross-category: absolute-with-suffix (relative would resolve to non-existent
// `src/media/...` in consumer's flat tree).
import { MediaCarousel } from "@/registry/components/media/media-carousel/media-carousel";
import { EngagementBar } from "../../engagement-bar/engagement-bar";
import { PostHeader } from "./post-header";
import { PollWidget } from "./poll-widget";
import { RepostOfCard } from "./repost-of-card";
import type { VariantInnerProps } from "./variant-shared";

/** The header: the host's `renderHeader` (it still gets the actions menu) or the default one. */
export function buildHeaderNode(p: VariantInnerProps, compact: boolean): ReactNode {
  const { post } = p;
  if (p.renderHeader) {
    return p.renderHeader(post, { currentUser: p.currentUser, kebab: p.kebab });
  }
  return (
    <PostHeader
      post={post}
      kebab={p.kebab}
      headingAs={p.headingAs}
      formattedTime={p.formattedTime}
      authorId={p.authorId}
      locale={p.locale}
      timeZone={p.timeZone}
      authorHref={p.getAuthorHref?.(post.author, post)}
      LinkComponent={p.LinkComponent}
      subtitle={typeof p.subtitle === "function" ? p.subtitle(post) : p.subtitle}
      labels={p.labels}
      onLocationClick={p.onLocationClick}
      onMentionClick={p.onMentionClick}
      compact={compact}
      className={p.headerClassName}
    />
  );
}

/** The engagement bar: the host's `renderEngagementBar` or the built-in one. */
export function buildEngagementNode(p: VariantInnerProps, compactBar: boolean): ReactNode {
  if (p.renderEngagementBar) {
    return p.renderEngagementBar(p.post, { actions: p.engagementActions });
  }
  const barProps = p.engagementBarProps;
  return (
    <EngagementBar
      ref={p.engagementBarRef}
      {...barProps}
      variant={compactBar ? "compact" : undefined}
      actions={p.engagementActions}
      onSubscribeDelta={p.engagementSubscribeNoop}
      labels={p.engagementLabels}
      locale={p.locale}
      formatCount={barProps?.formatCount ?? p.formatCount}
      optimistic={barProps?.optimistic ?? p.optimistic}
    />
  );
}

/** The media carousel (feed + detail). `mediaProps` goes first so `items` / `variant` stay the card's. */
export function buildMediaNode(p: VariantInnerProps): ReactNode {
  const { post } = p;
  if (!post.media || post.media.length === 0) return null;
  if (p.renderMedia) return p.renderMedia(post.media, { onDoubleTap: p.onMediaDoubleTap });
  return (
    <MediaCarousel
      {...p.mediaProps}
      items={post.media}
      variant="gallery"
      locale={p.locale}
      onDoubleTap={p.onMediaDoubleTap}
    />
  );
}

/** The poll (feed + detail): the host's `renderPoll`, the default widget, or nothing. */
export function buildPollNode(p: VariantInnerProps): ReactNode {
  const { post } = p;
  if (p.disablePollRender || !post.poll) return null;
  if (p.renderPoll) {
    return p.renderPoll(post, { onVote: p.onPollVote, isOwnerView: p.isOwnerView });
  }
  return (
    <PollWidget
      poll={post.poll}
      hasVoted={post.poll.hasVoted ?? false}
      isOwnerView={p.isOwnerView}
      optimisticVoteOptionId={post.poll.viewerVoteOptionId}
      optimisticIncrement={false}
      onVote={p.onPollVote}
      labels={{
        pollHeading: p.labels.pollHeading,
        pollTotalVotesLabel: p.labels.pollTotalVotesLabel,
        pollClosesAtLabel: p.labels.pollClosesAtLabel,
        pollClosedLabel: p.labels.pollClosedLabel,
      }}
      formatRelativeTime={p.formatRelativeTime}
      formatCount={p.formatCount}
      now={p.now}
      locale={p.locale}
      busy={p.pollBusy}
    />
  );
}

/** The nested repost mini-card (feed + detail). */
export function buildRepostNode(p: VariantInnerProps): ReactNode {
  const { post } = p;
  if (p.disableRepostOfRender || !post.repostOf) return null;
  const onClick = p.onRepostOfClick;
  if (p.renderRepostOf) {
    return p.renderRepostOf(post, {
      onClick: onClick ? () => post.repostOf && onClick(post.repostOf) : undefined,
    });
  }
  return (
    <RepostOfCard
      originalPost={post.repostOf}
      onClick={onClick}
      getHref={p.getHref}
      linkComponent={p.linkComponent}
      labels={p.cardLabels}
      locale={p.locale}
      timeZone={p.timeZone}
      now={p.now}
      formatRelativeTime={p.repostForwarding.formatRelativeTime}
      formatCount={p.repostForwarding.formatCount}
    />
  );
}

"use client";

import { useEffect, useLayoutEffect, useState } from "react";

const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export type Direction = "ltr" | "rtl";

/**
 * Resolves text direction (consumer contract C4 / R6): the `dir` prop wins; otherwise the
 * element's direction, read after mount — the computed `direction`, or the nearest explicit
 * non-`auto` `[dir]` ancestor (jsdom has no UA stylesheet for `dir`); otherwise `"ltr"`.
 *
 * The server render and the first client render both return the prop or `"ltr"`, so markup
 * must not depend on the resolved value before mount. Key handling, swipe, carousel and
 * transition logic may. A later direction change is not observed — pass `dir` if the app
 * switches direction at runtime without remounting.
 *
 * Directional props take `"start" | "end"`; physical values stay only as deprecated aliases.
 * Copy into a component's `hooks/`. Canonical copy: `_template/_snippets/` (tests next to it).
 */
export function useDirection(
  ref: React.RefObject<HTMLElement | null>,
  dirProp?: Direction,
): Direction {
  const [resolved, setResolved] = useState<Direction>("ltr");
  useIsoLayoutEffect(() => {
    if (dirProp) return;
    const el = ref.current;
    if (!el) return;
    const explicit = el.closest('[dir]:not([dir="auto"])')?.getAttribute("dir")?.toLowerCase();
    const rtl = getComputedStyle(el).direction === "rtl" || explicit === "rtl";
    setResolved(rtl ? "rtl" : "ltr");
  }, [dirProp, ref]);
  return dirProp ?? resolved;
}

import { useCallback, useEffect, useRef, type Dispatch, type SetStateAction } from "react";

export type InlinePanel = "none" | "likes" | "comments" | "share";

/**
 * Focus for the inline panels. The control that opened a panel gets focus back when the panel
 * closes while focus was inside it (or had fallen to <body>); if that control is gone, the card's
 * `<article>` (a `tabIndex=-1` target) does. Closing from elsewhere never moves focus.
 */
export function usePanelFocus(active: InlinePanel, setActive: Dispatch<SetStateAction<InlinePanel>>) {
  const panelEl = useRef<HTMLDivElement | null>(null);
  const opener = useRef<HTMLElement | null>(null);
  const restore = useRef<{ fallback: HTMLElement | null } | null>(null);
  const current = useRef(active);
  useEffect(() => {
    current.current = active;
  });

  const open = useCallback(
    (next: Exclude<InlinePanel, "none">) => {
      const el = document.activeElement;
      opener.current = el instanceof HTMLElement && el !== document.body ? el : null;
      setActive(next);
    },
    [setActive],
  );
  const close = useCallback(() => {
    const el = document.activeElement;
    const panel = panelEl.current;
    if (panel && (panel.contains(el) || el === document.body || el === null)) {
      restore.current = { fallback: panel.closest<HTMLElement>("article") };
    }
    setActive("none");
  }, [setActive]);
  const toggle = useCallback(
    (kind: Exclude<InlinePanel, "none">) => {
      if (current.current === kind) close();
      else open(kind);
    },
    [open, close],
  );
  useEffect(() => {
    const pending = restore.current;
    if (!pending || active !== "none") return;
    restore.current = null;
    const from = opener.current;
    (from && from.isConnected ? from : pending.fallback)?.focus();
  }, [active]);

  /** Ref callback for the element that wraps the open panel. */
  const panelRef = useCallback((el: HTMLDivElement | null) => {
    panelEl.current = el;
  }, []);

  return { open, close, toggle, panelRef };
}
